###Example: call this within exec tag after question:
###setZero(S7)
def setZero(qid):
    if qid.displayed:
        for eachRow in [row for row in qid.rows if row.displayed]:
            for eachCol in [col for col in qid.cols if col.displayed]:
                if eachRow[eachCol.index].val in ['', None]:
                    eachRow[eachCol.index].val = 0

###Example: call this within validate tag at question:
###OtherSpecify('r5')
def OtherSpecify(code):
    for eachRow in [this.attr(row) for row in [code]]:
        if len([1 for eachCol in this.cols if this.rows[eachRow.index][eachCol.index].val not in [0, "", None]]) gt 0 and eachRow.open in ["", None]:
            error(this.lget("extraInfo"), eachRow)
        elif len([1 for eachCol in this.cols if this.rows[eachRow.index][eachCol.index].val not in [0, "", None]]) == 0 and eachRow.open not in ["", None]:
            error(this.lget("extraSelect"), eachRow)


def checkOthLen(code,chklen=2):  ## UPDATED APR 2022 ##
    for eachRow in [eval("this.%s" % row) for row in [code]]:
        if eachRow and eachRow.open not in ["", None]:
            if len(eachRow.open.decode('utf-8').replace(' ','')) lt chklen:
                error(res.otherErr3, row = eachRow)

def group_rows( question, grouped_rows ):
    first_item_index = None
    shuffle_order = [row.index for row in question.rows.order]

    for index, row in enumerate( shuffle_order ):
        if question.rows[row].label in grouped_rows:
            if first_item_index == None:
                first_item_index = index
            else:
                first_item_index += 1
                shuffle_order.insert( first_item_index, shuffle_order.pop(index) )

    question.rows.order = shuffle_order

def group_rows_with_order( question, grouped_rows ):
    current_order = [row.index for row in question.rows.order]
    new_order     = []

    grouped_rows     = [question.attr(row).index for row in grouped_rows]
    first_item_index = current_order.index(grouped_rows[0])

    current_order.insert(first_item_index, grouped_rows)

    for row in current_order:
        if row == grouped_rows:
            new_order = new_order + row
        elif row not in grouped_rows:
            new_order.append(row)

    question.rows.order = new_order
